"use strict";exports.id=185,exports.ids=[185],exports.modules={83185:(a,b,c)=>{c.d(b,{TD:()=>e,fm:()=>f,mo:()=>h,sm:()=>d,w7:()=>i,wZ:()=>g});let d={name:"Omonbek Xojamurodov",brandTitle:"Omonbek",role:"Software Engineer & Frontend Architect",badge:"Frontend Engineering \xb7 Next.js & TypeScript",heroTitle:"Yuqori yuklamali veb-tizimlar uchun muhandislik arxitekturasi.",heroDescription:"React, Next.js va TypeScript yordamida murakkab veb-ilovalar, ko‘p-ijarachili (multi-tenant) CRM/ERP tizimlari, Feature-Sliced Design (FSD) arxitekturasi va biznes avtomatlashtirish platformalarini qurish bo‘yicha ixtisoslashuv.",location:"Toshkent, O‘zbekiston (Global Remote)",phone:"+998 77 777 45 02",email:"info@eval42.uz",statusText:"All systems operational",availability:"Yangi arxitektura va muhandislik loyihalari uchun ochiq"},e=[{label:"Xizmatlar",href:"#services"},{label:"Loyihalar",href:"#projects",badge:"3 Case"},{label:"Tajriba",href:"#experience"},{label:"Stek",href:"#stack"},{label:"FAQ",href:"#faq"}],f=[{id:"frontend-microfrontend",number:"01",title:"Frontend & Micro-Frontend Architecture",subtitle:"Next.js App Router \xb7 Server Components \xb7 Strict TypeScript",description:"React, Next.js (SSR/ISR/Server Components) va TypeScript asosida masshtablashuvchi, yuqori tezlikdagi veb-ilovalarni loyihalash. Izolyatsiyalangan modul chegaralari va nolga yaqin client-side JS yuklamasi.",colSpan:2,accentColor:"#635bff",tags:["Next.js 15","React Server Components","Micro-Frontends","TypeScript Strict"],visualType:"microfrontend",keyMetric:{label:"First Load JS qisqarishi",value:"-64% Bundle"}},{id:"api-state-management",number:"02",title:"API Integratsiya va State Management",subtitle:"REST API \xb7 TanStack Query \xb7 Zustand / Redux \xb7 Auth",description:"Backend xizmatlari bilan tiplangan (Type-Safe) integratsiya, ma’lumotlarni aqlli keshlash, optimistik UI yangilanishlari va murakkab global state boshqaruvi.",colSpan:1,accentColor:"#00d4ff",tags:["REST API","TanStack Query","Zustand / Redux","JWT Auth"],visualType:"realtime",keyMetric:{label:"Kesh Samaradorligi",value:"99.4% HIT"}},{id:"business-automation",number:"03",title:"Biznes Avtomatlashtirish va Hisobot Modullari",subtitle:"Murakkab Jadvallar \xb7 Filtrlash \xb7 Excel/PDF Eksport",description:"Katta hajmdagi ma’lumotlar jadvallari, ko‘p qatlamli qidiruv/filtrlash va avtomatlashtirilgan Excel (.xlsx) hamda PDF eksport tizimlarini yuqori tezlikda ishlashini ta’minlash.",colSpan:1,accentColor:"#0073e6",tags:["Excel/XLSX Engine","Data Tables","Multi-Filter","PDF Reports"],visualType:"automation",keyMetric:{label:"Jadval Render Tezligi",value:"1.2 soniya"}},{id:"crm-erp-dashboards",number:"04",title:"CRM, ERP va Boshqaruv Panellari",subtitle:"Admin Dashboards \xb7 Analitik Grafiklar \xb7 RBAC \xb7 Murakkab Formalar",description:"Biznes jarayonlarini boshqarish uchun ko‘p rolli (RBAC) admin panellar, interaktiv statistik diagrammalar va ko‘p bosqichli murakkab formalar tizimini noldan qurish.",colSpan:2,accentColor:"#635bff",tags:["CRM / ERP UI","RBAC Rollar","Analitik Grafiklar","React Hook Form + Zod"],visualType:"infrastructure",keyMetric:{label:"Interfeys Silliqligi",value:"60 FPS UI"}}],g=[{id:"education-crm-platform",index:"01",category:"Multi-Tenant SaaS \xb7 Security & FSD Architecture",title:"Education CRM Platform (Multi-Tenant SaaS)",roleAndPeriod:"Frontend Developer \xb7 Next.js, TypeScript, TanStack Query \xb7 2024–2025",clientType:"O‘quv Markazlar Uchun Onlayn Boshqaruv Tizimi",taskDescription:"O‘quv markazlar uchun onlayn CRM platforma: har bir o‘quv markaz o‘z subdomenida ishlaydi, 7 xil rol (admin, o‘qituvchi, o‘quvchi va boshqalar) o‘z panelini ko‘radi. Men frontend xavfsizligi va kod arxitekturasi ustida ishladim.",architectureHighlights:["7 xil foydalanuvchi roli uchun xavfsiz kirish va RBAC tizimi: tokenlar URL va brauzer xotirasidan server boshqaruvidagi httpOnly cookie’larga ko‘chirildi hamda sessiyani avtomatik yangilash (auto-refresh) yo‘lga qo‘yildi.","Frontendda multi-tenant izolyatsiya: har bir o‘quv markaz o‘z subdomenida ishlaydi va foydalanuvchi tokeniga mosligi API Gateway darajasida tekshiriladi.","730 ta fayl va ~64,000 qatorli kod bazasi Feature-Sliced Design (FSD) arxitekturasiga o‘tkazildi: aylanali bog‘liqliklar (circular dependencies) 8 tadan 2 taga, lint xatolari esa 182 tadan 23 taga tushirildi va qoidalar har bir commitda avtomatik tekshiriladi."],deepCaseStudy:{stackSummary:"Next.js, TypeScript, TanStack Query, Feature-Sliced Design (FSD). Backend: Django + Go (jamoa).",challenges:[{title:"Muammo 1: Xavfsizlik va Tokenlar himoyasi",problem:"Tokenlar URL orqali uzatilardi, sahifalarda rol tekshiruvi yo‘q edi (himoya faqat API xatosiga tayanardi).",solution:"Next.js server qatlamida httpOnly cookie joriy qilindi, 401 bo‘lsa server o‘zi sessiyani yangilaydi, rol bo‘yicha Guard va subdomenlar orasida tokensiz xavfsiz o‘tish qurildi.",result:"Brauzer JavaScript’i tokenni umuman ko‘rmaydi — XSS orqali token o‘g‘irlanishi yo‘li to‘liq yopildi."},{title:"Muammo 2: Chigallashgan kod bazasi (730 fayl / ~64k qator)",problem:"8 ta feature bir-biriga aylana bo‘lib bog‘langan edi, bitta o‘zgarish hammasini buzishi mumkin edi.",solution:"Bog‘liqlikni graf sifatida tahlil qilib, 20 ta modulni to‘g‘ri FSD qatlamiga ko‘chirdim va qoidani ESLint orqali har bir commitda avtomatik majburiy qildim.",result:"Aylanali guruhlar 8 → 2, qoidabuzarliklar 182 → 23 ga tushdi, tsc va production build toza holatga keldi."}],takeaway:"Nimani o‘rgandim: Ko‘p-ijarachili (multi-tenant) arxitekturada xavfsizlik chegarasi frontend emas, gateway’da turadi. Frontend vazifasi — foydalanuvchi tajribasi va tokenni xavfsiz saqlash."},technologies:["Next.js","TypeScript","TanStack Query","Feature-Sliced Design (FSD)","httpOnly Cookies","Multi-Tenant RBAC"],metrics:[{label:"Foydalanuvchi Rollari",value:"7 ta Rol",trend:"httpOnly + RBAC Guard"},{label:"Aylanali Bog‘liqliklar",value:"8 → 2",trend:"730 fayl (~64k qator)"},{label:"Lint Qoidabuzarliklar",value:"182 → 23",trend:"Avtomatik ESLint nazorat"}],mockupType:"education-crm",accentColor:"#635bff"},{id:"halalhub-food-marketplace",index:"02",category:"US Food Marketplace \xb7 Payments, Maps & Quality Audit",title:"HalalHub (US Food Marketplace)",roleAndPeriod:"Frontend Developer \xb7 Next.js 16, React 19, Stripe, Google Maps \xb7 2025",clientType:"AQSh Bozoridagi Taom Buyurtma Marketplace Platformasi",taskDescription:"Amerika bozoriga mo‘ljallangan taom buyurtma marketplace’i. Men to‘lov tizimi, xarita, autentifikatsiya, 4 til lokalizatsiyasi va topshirish oldidan sifat auditi ustida ishladim.",architectureHighlights:["Mijozlar uchun asosiy oqimlar: Stripe orqali onlayn to‘lovlar, Apple va Google orqali tezkor kirish, Google Maps xarita integratsiyasi va 4 ta til (EN / RU / UZ / AR).","Kesh to‘qnashuvlarining (cache collisions) oldini olish: barcha ma’lumot olish so‘rovlari (data-fetching keys) yagona tiplangan `qk` reestriga birlashtirildi.","Topshirish oldidan (pre-handover) audit: 13 ta muammo (API kalitlar xavfsizligi, error/loading holatlar, ishlatilmayotgan kutubxonalar va i18n) 6 ta commitda yechildi va har biri type-check, lint hamda production build bilan tasdiqlandi."],deepCaseStudy:{stackSummary:"Next.js 16, React 19, TanStack Query, Stripe, Google Maps, i18n (EN/RU/UZ/AR).",constraintOrNote:"Cheklov: Backendni o‘zgartirib bo‘lmasdi — barcha tuzatishlar faqat frontend tomonda (Next.js BFF route’lar yordamida) bajarilishi kerak edi.",challenges:[{title:"Muammo 1: Feature’lar orasida Kesh To‘qnashuvi (Cache Collisions)",problem:"Turli feature’lar bir xil query key ishlatgani uchun TanStack Query keshlari bir-birini ustiga yozib yuborardi.",solution:"Barcha so‘rov kalitlarini bitta qat’iy tiplangan `qk` registry’ga yig‘dim va har bir feature uchun alohida root ajratdim.",result:"Kesh to‘qnashuvlari to‘liq bartaraf etildi va ma’lumotlar sinxronligi 100% kafolatlandi."},{title:"Muammo 2: Topshirish oldidan sifat va xavfsizlik auditi",problem:"Topshirishdan oldin mijoz sinmagan va tugallanmagan joylarni (API kalitlar ochiqligi, xato/yuklanish holatlari, chala tarjimalar) topmasligi kerak edi.",solution:"Raqamlangan batch tizimi joriy qilindi — har bir batchdan keyin majburiy `tsc` / `eslint` / `next build` tekshiruvi va alohida toza commit qilindi.",result:"13 ta muammo (API key xavfsizligi, error/loading states, unused deps, i18n) 6 ta tekshirilgan commitda to‘liq tuzatildi."}],takeaway:"Natija: Backendga tegmasdan Next.js BFF qatlami va qat’iy batch-audit yordamida loyiha production-ready holatda mijozga topshirildi."},technologies:["Next.js 16","React 19","TanStack Query","Stripe Payments","Google Maps","i18n (EN/RU/UZ/AR)"],metrics:[{label:"Hal Qilingan Muammolar",value:"13 ta",trend:"6 ta toza commitda"},{label:"Lokalizatsiya Qamrovi",value:"4 ta Til",trend:"EN \xb7 RU \xb7 UZ \xb7 AR"},{label:"Query Key Arxitekturasi",value:"Typed qk",trend:"0 Cache Collision"}],mockupType:"halalhub",accentColor:"#0073e6"},{id:"logistics-driver-director-system",index:"03",category:"On-Site UX Discovery \xb7 Fleet & Executive Dashboard",title:"Logistika: Haydovchilar va Rahbar Boshqaruv Tizimi",roleAndPeriod:"Frontend & Product Engineer \xb7 Next.js, TypeScript, Excel Engine \xb7 2024",clientType:"Logistika va Yetkazib Berish Biznesi Avtomatlashtiruvi",taskDescription:"Logistika biznesi uchun ichki boshqaruv platformasi: biznesning o‘ziga bevosita borib, haydovchilar va korxona rahbari bilan birga yurib, har ikki tomon uchun eng qulay bo‘lgan ish jarayoni (UX), lokatsiya nazorati va hisobotlar tizimini yaratdim.",architectureHighlights:["On-Site Biznes va UX Tahlil: bevosita ish jarayoniga kirib, haydovchilar va rahbar bilan birga yurib, real og‘riqli nuqtalarni o‘rgandim hamda yo‘lda chalg‘imasdan 2–3 bosishda ishlaydigan haydovchi interfeysini loyihaladim.","Rahbar uchun Boshqaruv va Lokatsiya Paneli: korxona rahbari har bir haydovchining joriy holatini, yo‘nalishini va bajarilgan buyurtmalarini qo‘ng‘iroqlarsiz bitta ekranda ko‘ra oladigan dashboard qurdim.","Ma’lumotlar bazasi sxemasi va Excel (.xlsx) hisobotlar moduli: qog‘oz va tarqoq jadvallar o‘rniga bir tugma orqali tayyor bo‘ladigan, rahbariyat uchun moslashtirilgan avtomatik Excel eksport dvigatelini ishlab chiqdim."],deepCaseStudy:{stackSummary:"Next.js, TypeScript, REST API, Real-Time Location Flow, Excel (.xlsx) Export Engine, Mobile-First Driver UX.",constraintOrNote:"Yondashuv: Tayyor shablon ko‘chirish o‘rniga biznesning ichiga kirib, haydovchi va rahbarning kunlik ishini jonli kuzatish orqali UX qarorlar qabul qilindi.",challenges:[{title:"Muammo 1: Haydovchilar uchun yo‘lda murakkab dasturdan foydalanish qiyinligi",problem:"Haydovchilar harakatda bo‘lgani sababli ko‘p maydonli murakkab formalarni to‘ldira olmasdi va tizimdan foydalanishdan qochardi.",solution:"Haydovchilar bilan birga yurib, ularning odatlarini o‘rgandim va ekranda faqat eng zarur yirik tugmalar, tezkor status almashinuvi hamda avtomatik geoma’lumot yuborish oqimini qildim.",result:"Haydovchilar qo‘shimcha o‘qitishsiz tizimga tez moslashdi va buyurtma holatini belgilash vaqti bir necha soniyagacha qisqardi."},{title:"Muammo 2: Rahbar uchun shaffoflik va hisobotlarning qo‘lda yig‘ilishi",problem:"Rahbar kim qayerda ekanini bilish uchun doimiy qo‘ng‘iroq qilar, kunlik va oylik hisobotlar esa ko‘p vaqt olardi.",solution:"Rahbar uchun barcha faol reyslarni jonli ko‘rsatuvchi markaziy panel va ma’lumotlar bazasidan to‘g‘ridan-to‘g‘ri formatlangan `.xlsx` (Excel) hisobot chiqarib beruvchi modul yaratdim.",result:"Boshqaruv to‘liq shaffoflashdi va rahbar uchun hisobot tayyorlash vaqti soatlardan 1–2 soniyaga tushdi."}],takeaway:"Nimani o‘rgandim: Eng yaxshi mahsulot va UX ofisda taxmin qilish bilan emas, biznesning ichiga borib, haydovchi va rahbarning yonida yurib, ularning haqiqiy ehtiyojini tushunganda yaratiladi."},technologies:["Next.js","TypeScript","On-Site UX Research","Driver Mobile UI","Executive Dashboard","Excel (.xlsx) Export"],metrics:[{label:"Biznes Tahlil",value:"On-Site UX",trend:"Haydovchi + Rahbar"},{label:"Haydovchi Oqimi",value:"2-3 Bosish",trend:"Mobile-First UI"},{label:"Rahbar Hisoboti",value:".XLSX Auto",trend:"1 soniyada eksport"}],mockupType:"logistics-ux",accentColor:"#635bff"}],h=[{id:"faq-1",tag:"Arxitektura & FSD",question:"Omonbek Xojamurodov qaysi texnologiyalar va arxitekturada ishlaydi?",answer:"Asosiy ixtisoslashuv — Next.js (14/15/16 App Router), React 19, TypeScript (Strict Mode), TanStack Query, Zustand va Tailwind CSS. Yirik loyihalarda kod chigallashib ketmasligi uchun Feature-Sliced Design (FSD) arxitekturasi va ESLint chegara qoidalari qo‘llaniladi."},{id:"faq-2",tag:"Xavfsizlik & Multi-Tenant",question:"Ko‘p rolli (RBAC) va ko‘p subdomenli (Multi-Tenant) CRM/ERP tizimlarda xavfsizlik qanday ta’minlanadi?",answer:"Tokenlar brauzer xotirasida (localStorage) yoki URL’da saqlanmaydi. Next.js BFF server qatlami orqali httpOnly cookie’lardan foydalaniladi, 401 holatida sessiya serverda avtomatik yangilanadi va har bir rol (masalan, 7 xil rol) maxsus Route Guard orqali himoyalanadi."},{id:"faq-3",tag:"Mavjud Loyihalar Auditi",question:"Mavjud (chigallashgan yoki sekin ishlayotgan) frontend kod bazasini tartibga solib bera olasizmi?",answer:"Ha. Masalan, 730 ta fayl va 64,000 qatordan iborat CRM loyihada aylanali bog‘liqliklarni (circular dependencies) 8 tadan 2 taga, lint xatolarini 182 tadan 23 taga tushirib, kesh to‘qnashuvlarini yagona tiplangan `qk` reestri bilan to‘liq bartaraf etganman."},{id:"faq-4",tag:"Bog‘lanish & Hamkorlik",question:"Yangi loyiha bo‘yicha qanday bog‘lanish mumkin va javob vaqti qancha?",answer:"Saytdagi tezkor loyiha brifi formasi (xabar to‘g‘ridan-to‘g‘ri Telegram botga boradi), @the_khojamurodov Telegram manzili yoki +998 77 777 45 02 telefon raqami orqali bog‘lanishingiz mumkin. Odatda 2 soat ichida texnik javob beriladi."}],i=[{id:"github",name:"GitHub",handle:"@omonboyweb",href:"https://github.com/omonboyweb",platform:"github"},{id:"linkedin",name:"LinkedIn",handle:"in/omonbekxojamurodov",href:"https://www.linkedin.com/in/omonbekxojamurodov/",platform:"linkedin"},{id:"telegram",name:"Telegram",handle:"@the_khojamurodov",href:"https://t.me/the_khojamurodov",platform:"telegram"},{id:"phone",name:"Telefon",handle:"+998 77 777 45 02",href:"tel:+998777774502",platform:"phone"},{id:"email",name:"Email",handle:"info@eval42.uz",href:"mailto:info@eval42.uz",platform:"email"}]}};